          const endpoint = backdrop.querySelector('#mr-cp-url').value.trim();
          const apiKey = backdrop.querySelector('#mr-cp-header').value.trim();
          if (!name || !endpoint) return;
          state.customPlugins.push({ name, endpoint, apiKey, enabled: true });
          saveCustomPlugins();
          renderModalInner();
