      const file = e.target.files && e.target.files[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = () => {
        state.attachments.push({ type: 'image', name: file.name, dataUrl: reader.result });
        renderAttachmentTray();
      };
      reader.readAsDataURL(file);
