  // ============================================================================
  const USER_SETTINGS_KEY = 'pm_user_settings_v53';

  const defaultUserSettings = {
    displayName: 'Pixelmorphic Member',
    initials: 'PM',
    avatarBg: 'linear-gradient(135deg, #ea580c 0%, #d97706 100%)',
    planBadge: 'Pro',
    roleTitle: 'Workspace Member',
    email: '',
    locationCity: '',
    // Appearance & Custom UI Features
    themeMode: 'iron', // 'iron' | 'emerald' | 'dark' | 'cyber' | 'light' | 'oled'
    accentColor: '#10b981',
    fontScale: 'normal', // 'small' | 'normal' | 'large'
    compactCards: false,
    glassEffect: true,
    showScrollButtons: true,
    autoReadAloud: false,
    // Personalization
    customAbout: '',
    customStyle: 'Provide clear, structured, step-by-step explanations with high factual accuracy and practical code or examples.',
    tone: 'balanced', // 'balanced' | 'friendly' | 'concise' | 'academic'
    preferredLang: 'en',
    // Saved Memory
    memoryEnabled: true,
    memories: [],
    // Security
    pinLockEnabled: false,
    pinCode: '',
    twoFactorEnabled: true
  };

  function loadUserSettings() {
    try {
      const raw = JSON.parse(localStorage.getItem(USER_SETTINGS_KEY) || 'null');
      if (raw && typeof raw === 'object') {
        state.userSettings = { ...defaultUserSettings, ...raw, memories: Array.isArray(raw.memories) ? raw.memories : defaultUserSettings.memories };
        return state.userSettings;
      }
    } catch (_) {}
    state.userSettings = { ...defaultUserSettings };
    
    if (state.userSettings) {
      if (/Founder/i.test(state.userSettings.roleTitle || '')) state.userSettings.roleTitle = 'Pro Member';
      if (/Founder/i.test(state.userSettings.planBadge || '')) state.userSettings.planBadge = 'Plus';
    }
    return state.userSettings;
  }

  function saveUserSettings() {
    try { localStorage.setItem(USER_SETTINGS_KEY, JSON.stringify(state.userSettings)); } catch (_) {}
    applyUserAppearanceSettings();
    syncLeftSidebar();
    try {
      fetch('/api/research?chatMode=1', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ storageAction: 'save', userSettings: state.userSettings })
      }).catch(() => {});
    } catch (_) {}
  }

  const IRON_ARC_BG_URI_V73 = "data:image/jpeg;base64,";

  function tagSidebarButtonsForMechanicalTheme(isIronTheme) {
    try {
      const hash = (window.location.hash || '#chat').toLowerCase();
      let currentRouteKey = 'chat';
      if (hash.includes('code')) currentRouteKey = 'code';
      else if (hash.includes('study') || hash.includes('education')) currentRouteKey = 'study';
      else if (hash.includes('research') || hash.includes('business')) currentRouteKey = 'research';
      else if (hash.includes('image')) currentRouteKey = 'images';
      else if (hash.includes('library')) currentRouteKey = 'library';

      const sidebars = document.querySelectorAll('aside, .sidebar, .demo-sidebar');
      sidebars.forEach((sb) => {
        const items = sb.querySelectorAll('button, a, .demo-nav-item');
        items.forEach((el) => {
          if (el.id === 'mc-profile-pill-btn' || el.classList.contains('mc-hist-filter-pill') || el.classList.contains('mc-side-hist-del') || el.id === 'mc-sidebar-close-btn') {
            el.removeAttribute('data-pm-create-job');
            el.removeAttribute('data-pm-active-nav');
            return;
          }
          const txt = (el.textContent || '').trim();
          if (/^\+?\s*Create\s+a\s+job/i.test(txt)) {
            el.setAttribute('data-pm-create-job', '1');
            el.removeAttribute('data-pm-active-nav');
            return;
          } else {
            el.removeAttribute('data-pm-create-job');
          }

          let isMatch = false;
          if (currentRouteKey === 'chat' && /General\s*Chat/i.test(txt)) isMatch = true;
          else if (currentRouteKey === 'code' && /Code\s*Studio/i.test(txt)) isMatch = true;
          else if (currentRouteKey === 'study' && /Study\s*Workspace/i.test(txt)) isMatch = true;
          else if (currentRouteKey === 'research' && /Research\s*Lab/i.test(txt)) isMatch = true;
          else if (currentRouteKey === 'images' && /Image\s*Studio/i.test(txt)) isMatch = true;
          else if (currentRouteKey === 'library' && /^\s*🗂️?\s*Library/i.test(txt)) isMatch = true;

          if (isMatch && !state.hostPageActive) {
            el.setAttribute('data-pm-active-nav', '1');
            el.classList.add('active');
          } else if (!state.hostPageActive && /General\s*Chat|Code\s*Studio|Study\s*Workspace|Research\s*Lab|Image\s*Studio|Library/i.test(txt)) {
            el.removeAttribute('data-pm-active-nav');
            el.classList.remove('active');
          }
        });
      });

      // Tag the host top header bar ("Workspace / General Chat | API configured | Local test | Pricing")
      document.querySelectorAll('header, .topbar, .demo-topbar, .app-header, main > div:first-child, .main-content > div:first-child, .content > div:first-child').forEach((bar) => {
        if (bar.id === 'mc-dedicated-host-slot' || bar.id === 'mr-dedicated-host-slot' || bar.id === 'mc-shell-root' || bar.classList.contains('mc-shell')) return;
        const t = (bar.textContent || '');
        if (t.includes('API configured') || t.includes('Local test') || t.includes('Pricing') || bar.tagName === 'HEADER') {
          bar.setAttribute('data-pm-host-header', '1');
        }
      });

      const sendBtn = document.getElementById('mc-send-btn');
      if (sendBtn && !sendBtn.classList.contains('is-stop-mode')) {
        if (isIronTheme) {
          sendBtn.innerHTML = 'Send <span style="font-size:15px;line-height:1;margin-left:4px;">›</span>';
        } else {
          sendBtn.textContent = '↑';
        }
      }
    } catch (_) {}
  }

