  window.__pmApplyAppearance = applyUserAppearanceSettings;

  function toggleProfilePopover(anchorEl) {
    const existing = document.getElementById('mc-profile-popover');
    if (existing) {
      existing.remove();
      return;
    }
    const cfg = state.userSettings || loadUserSettings();
    const isGuestNow = isGuestModeActiveV66();
    const headInitials = isGuestNow ? 'GU' : (cfg.initials || 'PM');
    const headName = isGuestNow ? 'Guest Visitor' : (cfg.displayName || 'Pixelmorphic User');
    const headSub = isGuestNow ? 'Guest Mode - Click to Sign In' : (window.__pmLivePlanBadge || cfg.planBadge || 'Free');
    const headBg = isGuestNow ? 'linear-gradient(135deg, #475569, #1e293b)' : (cfg.avatarBg || 'linear-gradient(135deg, #10b981, #059669)');

    const pop = document.createElement('div');
    pop.id = 'mc-profile-popover';
    pop.className = 'mc-profile-popover';
    pop.style.zIndex = '1000002';

    if (anchorEl && anchorEl.getBoundingClientRect) {
      const r = anchorEl.getBoundingClientRect();
      if (r.top < 260) {
        pop.style.bottom = 'auto';
        pop.style.top = (r.bottom + 8) + 'px';
        pop.style.left = Math.max(12, Math.min(window.innerWidth - 280, r.left)) + 'px';
      } else {
        pop.style.bottom = Math.max(14, window.innerHeight - r.top + 8) + 'px';
        pop.style.left = Math.max(12, r.left) + 'px';
      }
    }

    pop.innerHTML = `
      <div class="mc-pop-user-head" data-open-set-tab="profile" style="cursor:pointer;">
        <span class="mc-avatar-circle" style="background:${headBg};">${esc(headInitials)}</span>
        <div style="flex:1;min-width:0;">
          <div style="font-size:14px;font-weight:700;color:#ffffff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${esc(headName)}</div>
          <div id="mc-pop-plan-sub" style="font-size:11.5px;color:#94a3b8;">${esc(headSub)}</div>
        </div>
        <span style="color:#94a3b8;font-size:16px;">›</span>
      </div>

      <div class="mc-pop-divider-line"></div>

      <button type="button" class="mc-pop-menu-btn" data-open-set-tab="billing">
        <span class="mc-pop-menu-icon">✨</span>
        <span>Upgrade plan &amp; Billing</span>
      </button>
      <button type="button" class="mc-pop-menu-btn" data-open-set-tab="personalization">
        <span class="mc-pop-menu-icon">🧠</span>
        <span>Personalization</span>
      </button>
      <button type="button" class="mc-pop-menu-btn" data-open-set-tab="memory">
        <span class="mc-pop-menu-icon">💾</span>
        <span>Saved Memory (${(cfg.memories || []).length})</span>
      </button>
      <button type="button" class="mc-pop-menu-btn" data-open-set-tab="profile">
        <span class="mc-pop-menu-icon">👤</span>
        <span>Profile</span>
      </button>
      <button type="button" class="mc-pop-menu-btn" data-open-set-tab="appearance">
        <span class="mc-pop-menu-icon">🎨</span>
        <span>UI Color &amp; Appearance</span>
        <span style="margin-left:auto;font-size:10.5px;padding:2px 7px;border-radius:999px;background:rgba(16,185,129,0.2);color:#6ee7b7;font-weight:700;">${esc((cfg.themeMode || 'emerald').toUpperCase())}</span>
      </button>
      <button type="button" class="mc-pop-menu-btn" data-open-set-tab="security">
        <span class="mc-pop-menu-icon">⚙️</span>
        <span>Settings &amp; Security</span>
      </button>

      <div class="mc-pop-divider-line"></div>

      <!-- Quick 1-Click Theme Switcher Strip inside Popover -->
      <div style="display:flex;align-items:center;justify-content:space-between;padding:5px 10px;">
        <span style="font-size:11px;color:#94a3b8;font-weight:600;">Theme:</span>
        <div style="display:flex;gap:4px;flex-wrap:wrap;">
          <button type="button" class="mc-calc-act-key ${cfg.themeMode === 'emerald' ? 'active' : ''}" data-quick-theme="emerald" title="Emerald Studio">🌿 Emerald</button>
          <button type="button" class="mc-calc-act-key ${cfg.themeMode === 'iron' ? 'active' : ''}" data-quick-theme="iron" title="Mechanical Iron-Tech HUD">⚙️ Iron</button>
          <button type="button" class="mc-calc-act-key ${cfg.themeMode === 'dark' ? 'active' : ''}" data-quick-theme="dark" title="Midnight Dark">🌙 Dark</button>
          <button type="button" class="mc-calc-act-key ${cfg.themeMode === 'light' ? 'active' : ''}" data-quick-theme="light" title="Pure Light">☀️ Light</button>
        </div>
      </div>

      <div class="mc-pop-divider-line"></div>

      <button type="button" class="mc-pop-menu-btn" data-open-set-tab="help">
        <span class="mc-pop-menu-icon">🛟</span>
        <span>Help &amp; Shortcuts</span>
        <span style="margin-left:auto;color:#94a3b8;">›</span>
      </button>
      <button type="button" class="mc-pop-menu-btn" id="mc-pop-logout-btn" style="color:#fca5a5;">
        <span class="mc-pop-menu-icon">↪️</span>
        <span>${isGuestNow ? 'Sign In / Create Account' : 'Log out / Switch Account'}</span>
      </button>
    `;

    document.body.appendChild(pop);

    // Handle all clicks inside popover via event delegation so no child span/icon ever misses!
    pop.addEventListener('click', (e) => {
      e.stopPropagation();

      const tabTrigger = e.target.closest('[data-open-set-tab]');
      if (tabTrigger) {
        const tab = tabTrigger.getAttribute('data-open-set-tab') || 'profile';
        pop.remove();
        openSettingsCenterModal(tab);
        return;
      }

      const themeTrigger = e.target.closest('[data-quick-theme]');
      if (themeTrigger) {
        if (!state.userSettings) loadUserSettings();
        state.userSettings.themeMode = themeTrigger.getAttribute('data-quick-theme') || 'emerald';
        saveUserSettings();
        pop.remove();
        showDownloadToast('🎨 UI Theme switched to ' + state.userSettings.themeMode.toUpperCase());
        return;
      }

      const logoutTrigger = e.target.closest('#mc-pop-logout-btn');
      if (logoutTrigger) {
        pop.remove();
        try {
          localStorage.removeItem('morphic_auth_session_v62');
          sessionStorage.removeItem('morphic_guest_mode_v66');
        } catch (_) {}
        syncLeftSidebar();
        openGoogleOtpAuthModal('signin');
        return;
      }
    });

    setTimeout(() => {
      const closePop = (ev) => {
        if (pop.contains(ev.target)) return;
        pop.remove();
        document.removeEventListener('click', closePop);
      };
      document.addEventListener('click', closePop);
    }, 30);
  }
  
  // ============================================================================
  // v66.0 GUEST MODE GUARD + FULL-WIDE HD VISUAL SLIDE DECK & BRAND SHOWCASE
  // ============================================================================
  function isUserAuthenticatedV66() {
    try {
      const raw = localStorage.getItem('morphic_auth_session_v62');
      if (!raw) return false;
      const parsed = JSON.parse(raw);
      return Boolean(parsed && parsed.token && parsed.user && parsed.user.email);
    } catch (_) {
      return false;
    }
  }

  function isGuestModeActiveV66() {
    return !isUserAuthenticatedV66();
  }

  function requireAccountForAction(actionName = 'use this AI feature') {
    if (isUserAuthenticatedV66()) return true;
    showDownloadToast(`🔒 Sign Up or Sign In required to ${actionName}`);
    openGoogleOtpAuthModal('signup');
    return false;
  }
  window.__pmRequireAccountForAction = requireAccountForAction;
  window.openPixelmorphicAuthModal = function(tab) { openGoogleOtpAuthModal(tab || "signin"); };
  document.addEventListener("click", (e) => {
    if (!isGuestModeActiveV66()) return;
    const btn = e.target.closest("button");
    if (!btn) return;
    if (btn.closest("#mc-lock-screen-overlay") || btn.closest("#mc-settings-modal-backdrop")) return;
    const txt = (btn.textContent || "").trim();
    if (/^(Run Research|Start Research|Verify|Scan Web|Generate Report|Export PDF|Export CSV)$/i.test(txt)) {
      e.preventDefault();
      e.stopPropagation();
      requireAccountForAction('run Verified Research Lab');
    }
  }, true);

