    async function requestBackendOtp({ email, displayName, password, roleTitle, planBadge, mode, googleQuick }) {
      const statusEl = overlay.querySelector('#mc-auth-error-msg');
      const submitBtn = overlay.querySelector('#mc-auth-primary-btn');
      if (statusEl) {
        statusEl.style.display = 'none';
        statusEl.textContent = '';
      }
      if (submitBtn) {
        submitBtn.disabled = true;
        submitBtn.textContent = '📧 Sending Private 6-Digit OTP to Email...';
      }
      try {
        const resp = await fetch('/api/research?chatMode=1', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            authAction: 'sendOtp',
            email,
            displayName,
            password,
            roleTitle,
            planBadge,
            mode,
            isGoogleQuickAuth: Boolean(googleQuick)
          })
        });
        const data = await resp.json();
        if (!resp.ok || !data.ok) {
          if (statusEl) {
            statusEl.style.display = 'block';
            statusEl.textContent = (data && data.error) || 'Could not send OTP. Please check your details.';
          }
          if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.textContent = mode === 'signup'
              ? '✨ Create Account & Email Private 6-Digit OTP →'
              : (mode === 'reset' ? '🔑 Email Password Reset 6-Digit OTP →' : '🔐 Sign In & Email Private 6-Digit OTP →');
          }
          return;
        }
        pendingEmail = data.email || email;
        pendingName = data.displayName || displayName || email.split('@')[0];
        smtpDelivered = Boolean(data.smtpSent);
        smtpConfiguredOnServer = Boolean(data.smtpConfigured);
        smtpErrorReason = String(data.smtpReason || '');
        isGoogleQuickAuth = Boolean(googleQuick);
        currentStep = 'otp-verify';
        secondsRemaining = 600;
        renderAuthModal();
      } catch (err) {
        if (statusEl) {
          statusEl.style.display = 'block';
          statusEl.textContent = 'Network error while sending OTP: ' + (err.message || 'Unknown error');
        }
        if (submitBtn) {
          submitBtn.disabled = false;
          submitBtn.textContent = 'Retry Sending 6-Digit OTP →';
        }
      }
    }

    async function verifyBackendOtp(otpString) {
      const statusEl = overlay.querySelector('#mc-auth-error-msg');
      const verifyBtn = overlay.querySelector('#mc-otp-verify-btn');
      if (otpString.length !== 6) {
        if (statusEl) {
          statusEl.style.display = 'block';
          statusEl.textContent = 'Please enter all 6 digits of the private OTP sent to your email.';
        }
        return;
      }
      if (verifyBtn) {
        verifyBtn.disabled = true;
        verifyBtn.textContent = '⚡ Verifying Private 6-Digit OTP...';
      }
      try {
        const resp = await fetch('/api/research?chatMode=1', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            authAction: 'verifyOtp',
            email: pendingEmail,
            otpCode: otpString
          })
        });
        const data = await resp.json();
        if (!resp.ok || !data.ok) {
          if (statusEl) {
            statusEl.style.display = 'block';
            statusEl.textContent = (data && data.error) || 'Invalid 6-digit OTP code. Please check your email and try again.';
          }
          if (verifyBtn) {
            verifyBtn.disabled = false;
            verifyBtn.textContent = '✅ Verify Private OTP & Enter Pixelmorphic AI';
          }
          return;
        }
        stopTimer();
        const verifiedUser = data.user || {};
        const cfg = state.userSettings || loadUserSettings();
        cfg.displayName = verifiedUser.displayName || pendingName;
        cfg.email = verifiedUser.email || pendingEmail;
        cfg.emailHandle = verifiedUser.email || pendingEmail;
        cfg.initials = verifiedUser.initials || 'PM';
        cfg.avatarBg = verifiedUser.avatarBg || 'linear-gradient(135deg, #10b981, #059669)';
        cfg.planBadge = verifiedUser.planBadge || 'Pro';
        cfg.roleTitle = verifiedUser.roleTitle || 'Team Member';
        saveUserSettings();

        rememberGoogleAccount(verifiedUser);
        try {
          localStorage.setItem('morphic_auth_session_v62', JSON.stringify({
            token: data.token,
            user: verifiedUser,
            verifiedAt: new Date().toISOString()
          }));
        } catch {}
        syncLeftSidebar();
        overlay.remove();
        showDownloadToast(`🎉 Verified! Welcome to Pixelmorphic AI, ${verifiedUser.displayName || pendingName}!`);
      } catch (err) {
        if (statusEl) {
          statusEl.style.display = 'block';
          statusEl.textContent = 'Verification error: ' + (err.message || 'Please retry');
        }
        if (verifyBtn) {
          verifyBtn.disabled = false;
          verifyBtn.textContent = '✅ Verify Private OTP & Enter Pixelmorphic AI';
        }
      }
    }

