  const CODE_STUDIO_STORAGE_KEY = 'pm_code_studio_v61';
  function balanceBrokenJsBlock(codeStr) {
  let inSingle = false, inDouble = false, inTemplate = false, inLineComment = false, inBlockComment = false;
  const stack = [];
  for (let i = 0; i < codeStr.length; i++) {
    const ch = codeStr[i];
    const next = codeStr[i + 1] || '';
    const prev = codeStr[i - 1] || '';

    if (inLineComment) {
      if (ch === '\n') inLineComment = false;
      continue;
    }
    if (inBlockComment) {
      if (ch === '*' && next === '/') { inBlockComment = false; i++; }
      continue;
    }
    if (inSingle) {
      if (ch === "'" && prev !== '\\') inSingle = false;
      continue;
    }
    if (inDouble) {
      if (ch === '"' && prev !== '\\') inDouble = false;
      continue;
    }
    if (inTemplate) {
      if (ch === '`' && prev !== '\\') inTemplate = false;
      continue;
    }

    if (ch === '/' && next === '/') { inLineComment = true; i++; continue; }
    if (ch === '/' && next === '*') { inBlockComment = true; i++; continue; }
    if (ch === "'") { inSingle = true; continue; }
    if (ch === '"') { inDouble = true; continue; }
    if (ch === '`') { inTemplate = true; continue; }

    if (ch === '{') stack.push('}');
    else if (ch === '(') stack.push(')');
    else if (ch === '[') stack.push(']');
    else if (ch === '}' || ch === ')' || ch === ']') {
      if (stack.length && stack[stack.length - 1] === ch) stack.pop();
    }
  }
  let closer = '';
  if (inSingle) closer += "'";
  if (inDouble) closer += '"';
  if (inTemplate) closer += '`';
  while (stack.length) closer += stack.pop();
  return closer + ';';
}

function repairTruncatedHtmlAndScripts(rawHtml) {
  let out = String(rawHtml || '').trim();
  if (!out) return out;

  // Strip any previously injected runtime script before repairing
  out = out.replace(/<script id="pm-v5[45678]-[^"]*">[\s\S]*?(?:<\/script>|$)/gi, '').trim();

  const lastScriptOpen = out.lastIndexOf('<script');
  const lastScriptClose = out.lastIndexOf('</script>');

  if (lastScriptOpen !== -1) {
    const tagEnd = out.indexOf('>', lastScriptOpen);
    if (tagEnd !== -1) {
      const hasClose = lastScriptClose > lastScriptOpen;
      let scriptBody = hasClose ? out.slice(tagEnd + 1, lastScriptClose) : out.slice(tagEnd + 1);

      let isValid = false;
      try {
        new Function(scriptBody);
        isValid = true;
      } catch (_) {}

      if (!isValid) {
        const lines = scriptBody.split('\n');
        for (let cut = lines.length - 1; cut >= 1; cut--) {
          const candidate = lines.slice(0, cut).join('\n').trim();
          if (!candidate) continue;
          const autoCloser = balanceBrokenJsBlock(candidate);
          for (const suffix of ['', autoCloser, '\n}', '\n});', '\n];', '\n}\n}', '\n}\n});', '\n}\n})();']) {
            try {
              new Function(candidate + suffix);
              scriptBody = candidate + suffix;
              isValid = true;
              break;
            } catch (_) {}
          }
          if (isValid) break;
        }
        if (!isValid) {
          scriptBody = '// Handled by Universal Runtime Engine\n';
        }
      }

      out = out.slice(0, tagEnd + 1) + '\n' + scriptBody + '\n  </script>\n</body>\n</html>';
    }
  }

  if (!/<\/body>/i.test(out)) out += '\n</body>';
  if (!/<\/html>/i.test(out)) out += '\n</html>';
  return out;
}

function auditCodeStudioHtml(htmlStr, userPrompt = '') {
  const html = String(htmlStr || '');
  const issues = [];
  if (html.lastIndexOf('<script') > html.lastIndexOf('</script>') || !/<\/html>\s*$/i.test(html.trim())) {
    issues.push('CRITICAL: Output was truncated before </script></body></html>.');
  }
  return issues;
}

